export async function GET(request: Request) {
  const { searchParams } = new URL(request.url);
  const query = searchParams.get('query');
  const category = searchParams.get('category');
  const minPrice = searchParams.get('minPrice');
  const maxPrice = searchParams.get('maxPrice');

  try {
    const minVal = minPrice ? parseFloat(minPrice) : 0;
    const maxVal = maxPrice ? parseFloat(maxPrice) : 999999;

    let whereClause: any = {
      basePrice: { gte: minVal, lte: maxVal }
    };

    if (category && category !== 'All') {
      whereClause.category = {
        name: category
      };
    }

    if (query) {
      whereClause.OR = [
        { name: { contains: query } },
        { description: { contains: query } }
      ];
    }

    const dbProducts = await prisma.product.findMany({
      where: whereClause,
      include: {
        store: true,
        category: true,
        variants: {
          include: {
            inventory: true
          }
        }
      }
    });

    const formattedProducts = dbProducts.map((p) => {
      const totalStock = p.variants.reduce((total, v) => {
        return total + v.inventory.reduce((sum, inv) => sum + inv.quantity, 0);
      }, 0);

      const mainVariant = p.variants[0];
      const sku = mainVariant ? mainVariant.sku : 'SKU-NONE';

      return {
        id: p.id,
        name: p.name,
        price: p.basePrice,
        category: p.category?.name || 'Uncategorized',
        rating: 4.5 + Math.random() * 0.5,
        image: getProductImage(p.category?.name || '', p.name),
        sku,
        stock: totalStock > 0 ? totalStock : 50,
        vendor: p.store?.name || 'Unknown',
        description: p.description || 'No description provided.'
      };
    });

    return NextResponse.json({ products: formattedProducts }, { status: 200 });
  } catch (err: any) {
    return NextResponse.json({ error: err.message }, { status: 500 });
  }
}

export async function POST(request: Request) {
  try {
    const body = await request.json();
    const { name, price, category, stock, sku, description, attributes, storeId } = body;

    if (!name || !price || !sku) {
      return NextResponse.json({ error: 'Name, Base Price and SKU are required.' }, { status: 400 });
    }

    let dbCategory = await prisma.category.findUnique({ where: { name: category } });
    if (!dbCategory) {
      dbCategory = await prisma.category.create({
        data: { name: category, slug: category.toLowerCase().replace(/\s+/g, '-') }
      });
    }

    let store = storeId ? await prisma.store.findUnique({ where: { id: storeId } }) : null;
    if (!store) {
      store = await prisma.store.findFirst();
    }

    if (!store) {
      return NextResponse.json({ error: 'No store found.' }, { status: 400 });
    }

    const existingVariant = await prisma.productVariant.findUnique({ where: { sku: sku.toUpperCase() } });
    if (existingVariant) {
      return NextResponse.json({ error: 'SKU code is already registered in catalog.' }, { status: 400 });
    }

    const newProduct = await prisma.$transaction(async (tx) => {
      const prod = await tx.product.create({
        data: {
          storeId: store.id,
          categoryId: dbCategory.id,
          name,
          basePrice: parseFloat(price),
          description,
          status: 'PUBLISHED'
        }
      });

      const variant = await tx.productVariant.create({
        data: {
          productId: prod.id,
          sku: sku.toUpperCase(),
          attributes: JSON.stringify(attributes || {}),
          price: parseFloat(price)
        }
      });

      const wh = await tx.warehouse.findFirst({ where: { storeId: store.id } });
      const qty = parseInt(stock) || 0;

      await tx.inventory.create({
        data: {
          variantId: variant.id,
          warehouseId: wh ? wh.id : null,
          quantity: qty,
          reorderPoint: 10
        }
      });

      return prod;
    });

    return NextResponse.json({ message: 'SKU published successfully.', product: newProduct }, { status: 201 });
  } catch (err: any) {
    return NextResponse.json({ error: err.message }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import jwt from 'jsonwebtoken';
import { getAuthUser, logAdminAction } from '@/lib/auth';

export async function POST(req: Request) {
  const user = await getAuthUser(req);
  if (!user) return NextResponse.json({ error: 'Unauthorized. Please sign in to place an order.' }, { status: 401 });

  try {
    const body = await req.json();
    const { items, shippingAddress, paymentMethod } = body;
    if (!items || items.length === 0) {
      return NextResponse.json({ error: 'Shopping cart items cannot be empty.' }, { status: 400 });
    }

    const customerId = user.id;

    const createdOrders = await prisma.$transaction(async (tx) => {
      // 1. Group items by their storeId
      const storeItemsMap = new Map<string, Array<{ dbVariant: any; quantity: number }>>();

      for (const item of items) {
        const sku = item.product?.sku;
        if (!sku) continue;

        const dbVariant = await tx.productVariant.findUnique({
          where: { sku },
          include: {
            product: { include: { store: true } },
            inventory: true
          }
        });

        if (!dbVariant) {
          throw new Error(`Product SKU ${sku} is no longer available.`);
        }

        const requestedQty = item.quantity || 1;
        const primaryInv = dbVariant.inventory[0];
        if (primaryInv && primaryInv.quantity < requestedQty) {
          throw new Error(`Insufficient stock for ${dbVariant.product.name}. Available: ${primaryInv.quantity}`);
        }

        // Deduct inventory
        if (primaryInv) {
          await tx.inventory.update({
            where: { id: primaryInv.id },
            data: { quantity: Math.max(0, primaryInv.quantity - requestedQty) }
          });
        }

        const storeId = dbVariant.product.storeId;
        if (!storeItemsMap.has(storeId)) {
          storeItemsMap.set(storeId, []);
        }
        storeItemsMap.get(storeId)!.push({ dbVariant, quantity: requestedQty });
      }

      if (storeItemsMap.size === 0) {
        throw new Error('No valid products found in order payload.');
      }

      const ordersList = [];

      // 2. Create dedicated Order record for each store
      for (const [storeId, storeItems] of Array.from(storeItemsMap.entries())) {
        let subTotal = 0;
        const orderItemsData = [];

        for (const sItem of storeItems) {
          const itemTotal = sItem.dbVariant.price * sItem.quantity;
          subTotal += itemTotal;

          orderItemsData.push({
            variantId: sItem.dbVariant.id,
            quantity: sItem.quantity,
            price: sItem.dbVariant.price
          });
        }

        const tax = Math.round(subTotal * 0.05);
        const shipping = 60.0; // ৳60 standard delivery
        const total = subTotal + tax + shipping;

        const order = await tx.order.create({
          data: {
            customerId,
            storeId,
            source: 'ONLINE',
            subTotal,
            tax,
            discount: 0.0,
            total,
            status: 'PENDING',
            items: {
              create: orderItemsData
            }
          },
          include: {
            store: true,
            items: { include: { variant: { include: { product: true } } } }
          }
        });

        ordersList.push(order);
      }

      return ordersList;
    });

    await logAdminAction(customerId, `ORDER_ONLINE_PLACED: OrdersCount=${createdOrders.length}`);

    // Create customer in-app notification
    await prisma.notification.create({
      data: {
        userId: customerId,
        title: 'Order Placed Successfully! 🛍️',
        body: `Your order (#${createdOrders[0].id.substring(0, 8).toUpperCase()}) has been received and sent to merchants for packing.`,
        type: 'SUCCESS',
        priority: 'HIGH',
        module: 'MARKETPLACE'
      }
    });

    return NextResponse.json({
      success: true,
      orders: createdOrders,
      orderId: createdOrders[0].id,
      total: createdOrders.reduce((sum, o) => sum + o.total, 0),
      message: 'Order recorded to database successfully!'
    }, { status: 201 });

  } catch (err: any) {
    console.error('Order Placement API Error:', err);
    return NextResponse.json({ error: err.message || 'Failed to place order.' }, { status: 400 });
  }
}

export async function GET(req: Request) {
  const user = await getAuthUser(req);
  if (!user) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });

  try {
    const role = user.role;
    let dbOrders;

    if (role === 'ADMIN' || role === 'SUPER_ADMIN' || role === 'MANAGER') {
      dbOrders = await prisma.order.findMany({
        include: {
          customer: { include: { profile: true } },
          store: true,
          items: { include: { variant: { include: { product: true } } } }
        },
        orderBy: { createdAt: 'desc' }
      });
    } else if (role === 'VENDOR_ADMIN' || role === 'SELLER') {
      const store = await prisma.store.findFirst({ where: { ownerId: user.id } });
      if (!store) return NextResponse.json({ orders: [] });

      dbOrders = await prisma.order.findMany({
        where: { storeId: store.id },
        include: {
          customer: { include: { profile: true } },
          store: true,
          items: { include: { variant: { include: { product: true } } } }
        },
        orderBy: { createdAt: 'desc' }
      });
    } else {
      dbOrders = await prisma.order.findMany({
        where: { customerId: user.id },
        include: {
          store: true,
          items: { include: { variant: { include: { product: true } } } }
        },
        orderBy: { createdAt: 'desc' }
      });
    }

    const formattedOrders = dbOrders.map((o: any) => {
      const cartItems = o.items.map((it: any) => ({
        product: {
          id: it.variant?.product?.id || it.id,
          name: it.variant?.product?.name || 'Product Item',
          price: it.price,
          sku: it.variant?.sku || 'SKU',
          image: 'https://images.unsplash.com/photo-1523275335684-37898b6baf30?w=500'
        },
        quantity: it.quantity
      }));

      return {
        id: o.id,
        date: o.createdAt.toISOString().split('T')[0],
        items: cartItems,
        total: o.total,
        subTotal: o.subTotal,
        status: o.status,
        source: o.source,
        storeName: o.store?.name || 'Zibonbaba Store',
        customerName: o.customer?.profile?.fullName || o.customer?.email || 'Marketplace Customer'
      };
    });

    return NextResponse.json({ orders: formattedOrders });
  } catch (err: any) {
    console.error('Orders GET API Error:', err);
    return NextResponse.json({ error: err.message }, { status: 500 });
  }
}
